<?php
namespace App\Services\Inbox;
use Illuminate\Support\Facades\{DB,Schema,Cache};
use Illuminate\Database\Schema\Blueprint;
class ReleaseSchema {
 public const COLUMNS=['inbox_businesses'=>['id','uuid','name','model','secrets','mock','live_enabled','graph_version','daily_limit','monthly_limit','input_rate','output_rate','max_output','last_worker_at','created_at','updated_at'],'inbox_members'=>['business_id','user_id'],'inbox_channels'=>['id','business_id','type','name','external_id','waba_id','credentials','instructions','delivery_policy','return_policy','store_delivery','return_page_id','default_mode','active','verified_at','created_at','updated_at'],'inbox_products'=>['channel_id','product_id'],'inbox_conversations'=>['id','business_id','channel_id','remote_hash','remote_secret','label','mode','takeover_by','unread','epoch','last_inbound_at','last_inbound_id','activity_at','created_at','updated_at'],'inbox_messages'=>['id','business_id','conversation_id','direction','kind','body','payload','external_id','dedupe','status','origin','source_id','actor_id','epoch','error_code','sent_at','delivered_at','read_at','created_at','updated_at'],'inbox_jobs'=>['id','business_id','type','reference_id','dedupe','state','attempts','available_at','reserved_at','error_code','created_at','updated_at'],'inbox_usage'=>['id','business_id','message_id','model','status','input_tokens','output_tokens','cost','error_code','created_at','updated_at'],'inbox_order_drafts'=>['id','business_id','conversation_id','product_id','stock_id','quantity','details','status','actor_id','created_at','updated_at'],'inbox_audit'=>['id','business_id','actor_id','action','reference_id','created_at','updated_at'],'inbox_receipts'=>['id','channel_id','external_id','status','error','dedupe','created_at','updated_at']];
 private static function cacheKey(){return 'inbox_schema_ready_v1_'.sha1(DB::connection()->getDatabaseName().DB::connection()->getTablePrefix());}
 public static function ready(){return Cache::remember(self::cacheKey(),60,function(){foreach(self::COLUMNS as $table=>$columns){if(!Schema::hasTable($table)||array_diff($columns,Schema::getColumnListing($table)))return false;}return true;});}
 public static function install(){
  if(DB::connection()->getDriverName()!=='mysql')throw new \RuntimeException('Inbox setup requires MySQL/InnoDB.');
  $key='inbox_schema_'.substr(hash('sha256',DB::connection()->getDatabaseName().DB::connection()->getTablePrefix()),0,30);
  $lock=DB::selectOne('SELECT GET_LOCK(?, 10) AS acquired',[$key]);if(!$lock||!(int)$lock->acquired)throw new \RuntimeException('Another setup is running. Try again shortly.');
  try{
   // Only fixed Inbox tables are created. Existing store/order data is never modified.
   // Existing tables must have the expected columns; do not silently repair incompatible schemas.
   foreach(self::COLUMNS as $table=>$columns)if(Schema::hasTable($table))foreach($columns as $column)if(!Schema::hasColumn($table,$column))throw new \RuntimeException('Existing Inbox schema is incompatible. Ask the developer to review it.');

  if(!Schema::hasTable('inbox_businesses'))Schema::create('inbox_businesses',function(Blueprint $t){$t->engine='InnoDB';$t->bigIncrements('id');$t->uuid('uuid')->unique();$t->string('name');$t->string('model')->default('gemini-3.5-flash-lite');$t->longText('secrets')->nullable();$t->boolean('mock')->default(true);$t->boolean('live_enabled')->default(false);$t->string('graph_version')->default('v26.0');$t->unsignedInteger('daily_limit')->default(100);$t->decimal('monthly_limit',12,6)->default(5);$t->decimal('input_rate',10,4)->default(.30);$t->decimal('output_rate',10,4)->default(2.50);$t->unsignedInteger('max_output')->default(512);$t->timestamp('last_worker_at')->nullable();$t->timestamps();});
  if(!Schema::hasTable('inbox_members'))Schema::create('inbox_members',function(Blueprint $t){$t->engine='InnoDB';$t->unsignedBigInteger('business_id');$t->unsignedBigInteger('user_id');$t->unique(['business_id','user_id']);});
  if(!Schema::hasTable('inbox_channels'))Schema::create('inbox_channels',function(Blueprint $t){$t->engine='InnoDB';$t->bigIncrements('id');$t->unsignedBigInteger('business_id')->index();$t->string('type',20);$t->string('name');$t->string('external_id',80);$t->string('waba_id',80)->nullable();$t->longText('credentials')->nullable();$t->text('instructions')->nullable();$t->text('delivery_policy')->nullable();$t->text('return_policy')->nullable();$t->boolean('store_delivery')->default(false);$t->unsignedBigInteger('return_page_id')->nullable();$t->string('default_mode',12)->default('draft');$t->boolean('active')->default(true);$t->timestamp('verified_at')->nullable();$t->timestamps();$t->unique(['type','external_id']);});
  if(!Schema::hasTable('inbox_products'))Schema::create('inbox_products',function(Blueprint $t){$t->engine='InnoDB';$t->unsignedBigInteger('channel_id');$t->unsignedBigInteger('product_id');$t->unique(['channel_id','product_id']);});
  if(!Schema::hasTable('inbox_conversations'))Schema::create('inbox_conversations',function(Blueprint $t){$t->engine='InnoDB';$t->bigIncrements('id');$t->unsignedBigInteger('business_id')->index();$t->unsignedBigInteger('channel_id')->index();$t->string('remote_hash',64);$t->text('remote_secret');$t->string('label')->default('Customer');$t->string('mode',12)->default('draft');$t->unsignedBigInteger('takeover_by')->nullable();$t->unsignedInteger('unread')->default(0);$t->unsignedInteger('epoch')->default(0);$t->timestamp('last_inbound_at')->nullable();$t->unsignedBigInteger('last_inbound_id')->nullable();$t->timestamp('activity_at')->nullable();$t->timestamps();$t->unique(['channel_id','remote_hash']);});
  if(!Schema::hasTable('inbox_messages'))Schema::create('inbox_messages',function(Blueprint $t){$t->engine='InnoDB';$t->bigIncrements('id');$t->unsignedBigInteger('business_id')->index();$t->unsignedBigInteger('conversation_id')->index();$t->string('direction',8);$t->string('kind',20)->default('text');$t->longText('body');$t->longText('payload')->nullable();$t->string('external_id',191)->nullable()->index();$t->string('dedupe',64)->unique();$t->string('status',24)->default('received');$t->string('origin',16)->default('customer');$t->unsignedBigInteger('source_id')->nullable();$t->unsignedBigInteger('actor_id')->nullable();$t->unsignedInteger('epoch')->default(0);$t->string('error_code',100)->nullable();$t->timestamp('sent_at')->nullable();$t->timestamp('delivered_at')->nullable();$t->timestamp('read_at')->nullable();$t->timestamps();});
  if(!Schema::hasTable('inbox_jobs'))Schema::create('inbox_jobs',function(Blueprint $t){$t->engine='InnoDB';$t->bigIncrements('id');$t->unsignedBigInteger('business_id')->index();$t->string('type',12);$t->unsignedBigInteger('reference_id');$t->string('dedupe',100)->unique();$t->string('state',20)->default('pending');$t->unsignedInteger('attempts')->default(0);$t->timestamp('available_at')->index();$t->timestamp('reserved_at')->nullable();$t->string('error_code',100)->nullable();$t->timestamps();});
  if(!Schema::hasTable('inbox_usage'))Schema::create('inbox_usage',function(Blueprint $t){$t->engine='InnoDB';$t->bigIncrements('id');$t->unsignedBigInteger('business_id')->index();$t->unsignedBigInteger('message_id')->nullable();$t->string('model');$t->string('status',20);$t->unsignedInteger('input_tokens')->default(0);$t->unsignedInteger('output_tokens')->default(0);$t->decimal('cost',12,6)->default(0);$t->string('error_code',100)->nullable();$t->timestamps();});
  if(!Schema::hasTable('inbox_order_drafts'))Schema::create('inbox_order_drafts',function(Blueprint $t){$t->engine='InnoDB';$t->bigIncrements('id');$t->unsignedBigInteger('business_id')->index();$t->unsignedBigInteger('conversation_id')->index();$t->unsignedBigInteger('product_id');$t->unsignedBigInteger('stock_id');$t->unsignedInteger('quantity')->default(1);$t->longText('details');$t->string('status')->default('needs_staff_review');$t->unsignedBigInteger('actor_id')->nullable();$t->timestamps();});
  if(!Schema::hasTable('inbox_audit'))Schema::create('inbox_audit',function(Blueprint $t){$t->engine='InnoDB';$t->bigIncrements('id');$t->unsignedBigInteger('business_id')->nullable()->index();$t->unsignedBigInteger('actor_id')->nullable();$t->string('action',100);$t->unsignedBigInteger('reference_id')->nullable();$t->timestamps();});
 
if(!Schema::hasTable('inbox_receipts'))Schema::create('inbox_receipts',function(Blueprint $t){$t->engine='InnoDB';$t->bigIncrements('id');$t->unsignedBigInteger('channel_id')->index();$t->string('external_id',191);$t->string('status',20);$t->integer('error')->default(0);$t->string('dedupe',64)->unique();$t->timestamps();});
   Cache::forget(self::cacheKey());if(!self::ready())throw new \RuntimeException('Inbox setup incomplete.');
  }finally{DB::selectOne('SELECT RELEASE_LOCK(?) AS released',[$key]);}
 }
}
